/** `owner/repo#number`, as the sign-in's redirect names the user's inbox issue (M1.2 §8.4). */
const INBOX = /^[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+#[0-9]+$/;

/**
 * Turns the redirect's `inbox` parameter into the issue's URL. The URL can be edited, so the
 * value must be exactly `owner/repo#number`: the link may point nowhere but a GitHub issue.
 *
 * @param value The `inbox` parameter, if present.
 * @returns The issue's URL on github.com, or `undefined` for a missing or invalid value.
 */
export const inboxUrl = (value: string | null): string | undefined => {
  if (value === null || !INBOX.test(value)) {
    return undefined;
  }
  const [repo = "", number = ""] = value.split("#");
  // `.` and `..` are no GitHub names; they would move the link off the repo's path
  if (repo.split("/").some((segment) => /^\.+$/.test(segment))) {
    return undefined;
  }
  return `https://github.com/${repo}/issues/${number}`;
};
